content.css:
.cardGrid {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing, 10px);
  padding: var(--padding, 10px);
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  align-content: flex-start;
}
.cardGrid.fitGrid {
  display: grid;
  gap: 0;
  align-content: stretch;
  justify-content: stretch;
}
.card {
  width: var(--card-width, 150px);
  height: var(--card-height, 100px);
  min-width: var(--card-width, 150px);
  min-height: var(--card-height, 100px);
  border: var(--border-width, 1px) solid var(--border-color, #d0d0d0);
  border-radius: var(--border-radius, 4px);
  background-color: var(--card-background, #ffffff);
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.card:hover {
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.15);
}
.cardGrid.fitGrid .card {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}
.card.dimmed {
  opacity: 0.35;
}
.card.selected,
.card.highlighted {
  opacity: 1;
  border-color: #2b78ff;
  box-shadow: 0 0 0 2px rgba(43, 120, 255, 0.2);
}
.cardTitle {
  background-color: var(--title-background, #f5f5f5);
  color: var(--title-color, #000000);
  font-size: var(--title-font-size, 14px);
  font-family: var(--title-font-family, "Segoe UI");
  font-weight: var(--title-font-weight, normal);
  font-style: var(--title-font-style, normal);
  text-decoration: var(--title-text-decoration, none);
  padding: var(--title-padding-v, 8px) var(--title-padding-h, 10px);
  text-align: var(--title-align, center);
  letter-spacing: var(--title-letter-spacing, 0px);
  line-height: var(--title-line-height, 1.2);
  box-sizing: border-box;
  border-bottom: 1px solid var(--border-color, #d0d0d0);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-shrink: 0;
  height: var(--title-height, auto);
}
.cardTitle.wrapTitle {
  white-space: normal;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cardContent {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
}
.cardValues {
  padding: 5px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: auto;
  flex: 1;
}
.cardValues.table {
  display: grid;
  grid-template-columns: repeat(var(--table-columns, 1), minmax(0, 1fr));
  gap: 4px;
}
.cardValues.table .valueRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: center;
  column-gap: 10px;
}
.cardValues.mosaic {
  display: grid;
  grid-template-columns: repeat(var(--mosaic-columns, 2), minmax(0, 1fr));
  gap: var(--mosaic-gap, 6px);
  align-content: start;
}
.valueRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
.cardValues.mosaic .valueRow {
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  border: 1px solid var(--border-color, #d0d0d0);
  border-radius: 4px;
  padding: 4px 6px;
  gap: 2px;
}
.cardValues.mosaic .valueLabel {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.valueLabel {
  color: var(--label-color, #666666);
  font-size: var(--label-font-size, 11px);
  font-family: var(--label-font-family, "Segoe UI");
  font-weight: var(--label-font-weight, normal);
  font-style: var(--label-font-style, normal);
  text-decoration: var(--label-text-decoration, none);
  text-align: var(--label-align, left);
  flex: 1 1 auto;
  white-space: nowrap;
}
.valueText {
  color: var(--value-color, #000000);
  font-size: var(--value-font-size, 16px);
  font-family: var(--value-font-family, "Segoe UI");
  font-weight: var(--value-font-weight, normal);
  font-style: var(--value-font-style, normal);
  text-decoration: var(--value-text-decoration, none);
  text-align: var(--value-align, right);
  flex: 0 0 auto;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cardValues.table .valueLabel,
.cardValues.table .valueText,
.cardValues.mosaic .valueLabel,
.cardValues.mosaic .valueText {
  width: 100%;
}
.chartContainer {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
